import {resources,subjects,filterResources} from './data.js';
const $=s=>document.querySelector(s);
const icon=(name,cls='')=>`<img src="assets/${name}.svg" alt="" class="${cls}">`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let saved=readLocal('juldp-saved',[]);if(!Array.isArray(saved))saved=[];
let profile=readLocal('juldp-profile',{branch:'B.Tech CSE',semester:'5',subjects:subjects.slice(0,3).map(s=>s.name)});if(!profile||!Array.isArray(profile.subjects))profile={branch:'B.Tech CSE',semester:'5',subjects:subjects.slice(0,3).map(s=>s.name)};
let category='For You',query='',page='home',toastTimer;
const categories=['For You','PYQs','Books','Research','E-Resources','My Subjects'];
const titles={home:'A little curiosity goes a long way.',discover:'Follow your curiosity.',search:'Find your next resource.',saved:'Good finds, kept close.',profile:'Your learning space.'};
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{notify('Your browser could not save this change. It will last for this visit.');return false;}}
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function saveButton(r){const isSaved=saved.includes(r.id);return `<button class="save-action ${isSaved?'saved':''}" data-save="${r.id}" aria-pressed="${isSaved}" aria-label="${isSaved?'Unsave':'Save'} ${escape(r.title)}">${icon(isSaved?'bookmark-filled':'bookmark')}<span>${isSaved?'Saved':'Save'}</span></button>`;}
function post(r){const book=r.type==='BOOK';return `<article class="resource-post" data-resource="${r.id}">
 <div class="post-header"><span class="type-icon">${icon(r.icon)}</span><div><strong>${r.type==='E-RESOURCE'?'E-RESOURCE':r.type} <span style="font-weight:400;color:var(--muted)">· ${escape(r.subject)}</span></strong><small>${book?'Selected for your reading list':r.type==='PYQ'?'From the question paper collection':r.type==='RESEARCH'?'A new perspective for curious minds':'More from your digital library'}</small></div>${r.tag?`<span class="post-tag">${r.tag}</span>`:''}</div>
 ${book?`<div class="book-layout"><img class="book-cover" src="${r.cover}" alt="${escape(r.title)} book cover" loading="lazy" width="91" height="125"><div><h2 class="resource-title"><button data-open="${r.id}">${escape(r.title)}</button></h2><p class="author">${escape(r.subtitle)}</p><p class="metadata">${r.subject} · ${r.code}</p><span class="available">Available in the library</span></div></div><div class="location-strip">${icon('map-pin')}<span><strong>Central Library · Floor 2</strong> · CS Section · Rack ${r.rack}</span><span class="call-number">${r.callNumber}</span></div>`:`<h2 class="resource-title"><button data-open="${r.id}">${escape(r.title)}</button></h2>${r.type==='PYQ'?`<p class="description">${r.subtitle} <span style="color:#b0b3bc">·</span> ${r.code}</p><div class="question-preview"><div><span class="preview-label">A QUESTION TO GET YOU THINKING</span><p>${r.preview}</p></div><div class="paper-year"><strong>${r.year}</strong><small>END SEMESTER</small></div></div><div class="metadata"><span>Semester ${profile.semester}</span><span>·</span><span>${r.pages} pages</span><span>·</span><span>Sample paper</span></div>`:`<p class="description">${r.description}</p>${r.type==='E-RESOURCE'?`<div class="digital-preview"><div><strong>${r.provider}</strong><span>${r.id==='ieee'?'ADVANCING TECHNOLOGY. INSPIRING IDEAS.':'THE IDEAS STARTING CLOSE TO HOME.'}</span></div>${icon('world')}</div>`:`<div class="discovery-topics">${r.topics.map(t=>`<button data-query="${r.subject}">${t}</button>`).join('')}</div>`}<div class="metadata">${r.subtitle}</div>`}`}
 <div class="post-actions"><button class="primary-action" data-open="${r.id}" ${book?'data-location="true"':''}>${icon(book?'map-pin':r.type==='PYQ'?'file-text':r.type==='RESEARCH'?'article':'world')}${r.action}</button>${r.type==='PYQ'?`<button class="text-action" data-related="${r.id}">${icon('books')}Related books</button>`:book?`<button class="text-action" data-catalog="${r.id}">View on OPAC ${icon('external-link')}</button>`:''}${saveButton(r)}</div></article>`;}
function empty(title,message,action='Browse the feed'){return `<div class="empty">${icon(page==='search'?'search':'bookmark')}<h2>${title}</h2><p>${message}</p><button class="primary-action" data-page="home">${action}</button></div>`;}
function render(){
 $('#page-title').textContent=titles[page]||titles.home;
 $('#search-input').value=query;
 $('#search-form').classList.toggle('search-visible',page==='search');
 $('#categories').hidden=page==='profile';
 $('#categories').innerHTML=categories.map(c=>`<button data-category="${c}" class="${c===category?'active':''}" aria-pressed="${c===category}">${c}</button>`).join('');
 document.querySelectorAll('[data-page]').forEach(el=>{el.classList.toggle('active',el.dataset.page===page);if(el.dataset.page===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 $('#saved-count').textContent=saved.length;
 $('.account small').textContent=`${profile.branch} · Semester ${profile.semester}`;
 $('.context-profile p').textContent=`${profile.branch} · Semester ${profile.semester}`;
 $('#subject-list').innerHTML=subjects.filter(s=>profile.subjects.includes(s.name)).slice(0,3).map(s=>`<button class="subject-row" data-query="${s.name}"><span class="subject-glyph">${s.short}</span><span><strong>${s.name}</strong><small>${s.code}</small></span>${icon('chevron-right')}</button>`).join('')||'<p class="description">Add subjects to personalize your feed.</p>';
 $('#trending-list').innerHTML=['cn-book','os-book','db-pyq'].map((id,i)=>{const r=resources.find(r=>r.id===id);return `<button class="trending-row" data-open="${id}"><span>0${i+1}</span><div><strong>${r.title}</strong><small>${r.type==='PYQ'?'2024 question paper':r.type.toLowerCase()} · ${r.subject}</small></div></button>`;}).join('');
 let content='';
 if(page==='profile'){content=`<section class="profile-view"><span class="avatar">AS</span><h2>Aarav Sharma</h2><p class="view-description">Make the library feel a little more like you.</p><form id="profile-form" class="profile-form"><label>Your programme<select name="branch"><option>B.Tech CSE</option><option>B.Tech ISE</option><option>B.Tech ECE</option></select></label><label>Your semester<select name="semester">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${String(i+1)===String(profile.semester)?'selected':''}>Semester ${i+1}</option>`).join('')}</select></label><fieldset><legend>Your interests and subjects</legend><div class="interest-options">${subjects.map(s=>`<label><input type="checkbox" name="subject" value="${s.name}" ${profile.subjects.includes(s.name)?'checked':''}>${s.name}</label>`).join('')}</div></fieldset><button class="primary-action" type="submit">Save preferences</button><p class="callout">Preferences and saved resources stay on this device. This demo collection contains CSE resources.</p></form></section>`;}
 else if(page==='search'){
  const matches=filterResources({category,query,selectedSubjects:profile.subjects});
  content=`<h2 class="view-heading">${query?`Results for “${escape(query)}”`:'A subject, a title, a spark.'}</h2><p class="view-description">${query?`${matches.length} resources found in the demo collection`:'Search across your university’s resource collection.'}</p>`;
  if(query){const matchedSubjects=subjects.filter(s=>`${s.name} ${s.code}`.toLowerCase().includes(query.toLowerCase()));if(matchedSubjects.length&&['For You','My Subjects'].includes(category))content+=`<h3 class="group-title">SUBJECTS</h3>${matchedSubjects.map(s=>`<button class="related-row" data-query="${s.name}"><span class="subject-glyph">${s.short}</span><span><strong>${s.name}</strong><small>${s.code}</small></span>${icon('chevron-right')}</button>`).join('')}`;for(const [type,label]of [['PYQ','QUESTION PAPERS'],['BOOK','BOOKS'],['RESEARCH','RESEARCH'],['E-RESOURCE','E-RESOURCES']]){const group=matches.filter(r=>r.type===type);if(group.length)content+=`<h3 class="group-title">${label}</h3>`+group.map(post).join('');}if(!matches.length&&!matchedSubjects.length)content+=empty('No matches just yet.','Try a subject such as Computer Networks, or a resource like IEEE Xplore.');}
  else content+=`<h3 class="group-title">TRY A SUBJECT</h3><div class="discovery-topics">${subjects.map(s=>`<button data-query="${s.name}">${s.name}</button>`).join('')}</div><h3 class="group-title">POPULAR FINDS</h3>`+resources.slice(0,2).map(post).join('');
 }else{
  let results=filterResources({category,selectedSubjects:profile.subjects,saved:page==='saved'?saved:null});
  if(page==='home'&&category==='For You'&&!subjects.slice(0,3).every(s=>profile.subjects.includes(s.name))){results.sort((a,b)=>Number(profile.subjects.includes(b.subject))-Number(profile.subjects.includes(a.subject)));}
  if(page==='saved')content=`<h2 class="view-heading">Your saved resources</h2><p class="view-description">${saved.length} ${saved.length===1?'find':'finds'} to come back to. Saved on this device.</p>`;
  else if(page==='discover')content=`<section class="discover-intro"><h2>There's more on the next shelf.</h2><p class="view-description">Go beyond your subjects. Find an idea worth following.</p><div class="discovery-topics"><button data-category="PYQs">Exam preparation</button><button data-category="Research">Research reading</button><button data-category="E-Resources">Digital resources</button><button data-category="Books">Recommended books</button></div></section>`;
  else content=`<div class="feed-context"><span>${icon('sparkles')}${category==='For You'?`Picked for ${escape(profile.branch)} · Semester ${escape(profile.semester)}`:category==='My Subjects'?'Connected to your interests':`${category} for your next discovery`}</span><button data-page="profile">Tune your feed</button></div>`;
  content+=results.length?results.map(post).join(''):empty(page==='saved'?'Keep a good find.':'Choose your next interest.',page==='saved'?'Tap Save on a resource and it will be waiting here when you need it.':'Add subjects to your profile to see related resources.');
 }
 $('#content').innerHTML=content;
 const branch=$('#profile-form select[name="branch"]');if(branch)branch.value=profile.branch;
}
function go(next){page=['home','discover','search','saved','profile'].includes(next)?next:'home';if(page!=='search')query='';render();window.scrollTo(0,0);if(page==='search')$('#search-input').focus();}
function setCategory(next){category=next;if(!['home','discover','search','saved'].includes(page))page='home';render();}
function openDetail(id,location=false){const r=resources.find(r=>r.id===id);if(!r)return;
 const book=r.type==='BOOK';
 $('#detail-content').innerHTML=`<p class="detail-type">${r.type} · ${escape(r.subject)}</p><h2 id="detail-title" class="detail-title">${r.title}</h2><p class="detail-context">${r.subtitle}</p>${book?`<div class="find-location" id="find-location"><span class="available">Available · Sample availability</span><h3 style="margin-top:12px">Find it in the library</h3><p class="description">Central Library · Floor 2 · CS Section</p><div class="location-path"><span>Rack ${r.rack}</span><span>Shelf ${r.shelf}</span><span>${r.callNumber}</span></div></div>`:r.type==='PYQ'?`<div class="question-preview"><div><span class="preview-label">SAMPLE QUESTION PAPER PREVIEW</span><p>1. ${r.preview}</p><p>2. Discuss the key concepts of ${r.subject.toLowerCase()} with suitable examples.</p></div><div class="paper-year"><strong>${r.year}</strong><small>${r.pages} PAGES</small></div></div><p class="callout">This is a sample paper preview. Official PDFs can be connected when the library supplies them.</p>`:`<p class="description">${r.description}</p><div class="detail-section"><h3>${r.id==='distributed'?'Explore this reading collection':'Access this resource'}</h3><p>${r.id==='distributed'?'Suggested topics: consistency, fault tolerance, and cloud computing. Browse the digital library for published research.':r.id==='dspace'?'This sample collection demonstrates discovery of campus projects and theses. An official repository link can be connected by the library.':'University access may require campus network or institutional sign-in.'}</p></div>`}
 <div class="post-actions">${r.url?`<a class="primary-action" href="${r.url}" target="_blank" rel="noopener noreferrer">Open IEEE Xplore ${icon('external-link')}</a>`:book?`<button class="primary-action" data-catalog="${r.id}">View catalogue information</button>`:r.id==='distributed'?`<a class="primary-action" href="https://ieeexplore.ieee.org/search/searchresult.jsp?queryText=distributed%20systems" target="_blank" rel="noopener noreferrer">Browse research ${icon('external-link')}</a>`:''}${saveButton(r)}</div>
 <section class="detail-section"><h3>Keep exploring</h3><p>Connected resources for your next step.</p>${r.related.map(id=>{const related=resources.find(r=>r.id===id);return `<button class="related-row" data-open="${id}"><span class="type-icon">${icon(related.icon)}</span><span><strong>${related.title}</strong><small>${related.type} · ${related.type==='PYQ'?related.year:related.subject}</small></span>${icon('chevron-right')}</button>`;}).join('')}</section><span class="mock-label">Prototype · Sample academic records</span>`;
 if(!$('#resource-dialog').open)$('#resource-dialog').showModal();$('#resource-dialog').scrollTop=0;
 if(location)$('#find-location')?.scrollIntoView({block:'nearest'});
}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-page],[data-category],[data-save],[data-open],[data-related],[data-query],[data-catalog]');if(!button)return;
 if(button.dataset.page){if(button.tagName!=='A')location.hash=button.dataset.page;else if(location.hash===button.getAttribute('href'))go(button.dataset.page);}
 if(button.dataset.category){setCategory(button.dataset.category);if(location.hash!=='#'+page)location.hash=page;}
 if(button.dataset.query){query=button.dataset.query;category='For You';page='search';location.hash='search';render();$('#search-input').focus();}
 if(button.dataset.open)openDetail(button.dataset.open,button.hasAttribute('data-location'));
 if(button.dataset.related){const r=resources.find(r=>r.id===button.dataset.related);openDetail(r.related.find(id=>resources.find(x=>x.id===id).type==='BOOK'));}
 if(button.dataset.catalog){openDetail(button.dataset.catalog,true);notify('Sample catalogue record. An official OPAC link has not been connected.');}
 if(button.dataset.save){const id=button.dataset.save;const wasSaved=saved.includes(id);saved=wasSaved?saved.filter(x=>x!==id):[...saved,id];const stored=persist('juldp-saved',saved);render();if($('#resource-dialog').open){document.querySelectorAll(`#resource-dialog [data-save="${id}"]`).forEach(el=>{el.outerHTML=saveButton(resources.find(r=>r.id===id));});}if(stored)notify(wasSaved?'Removed from your saved resources.':'Saved for your next study session.');}
});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();query=$('#search-input').value;page='search';location.hash='search';render();$('#search-input').focus();});
$('#search-input').addEventListener('input',e=>{query=e.target.value;if(page!=='search'){page='search';location.hash='search';}const cursor=e.target.selectionStart;render();$('#search-input').focus();$('#search-input').setSelectionRange(cursor,cursor);});
document.addEventListener('submit',e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const form=new FormData(e.target);profile={branch:form.get('branch'),semester:form.get('semester'),subjects:form.getAll('subject')};const stored=persist('juldp-profile',profile);render();if(stored)notify('Your learning preferences have been updated.');});
$('.dialog-close').addEventListener('click',()=>$('#resource-dialog').close());
$('#resource-dialog').addEventListener('click',e=>{if(e.target===$('#resource-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)e.target.close();}});
$('#updates').addEventListener('click',()=>{page='discover';category='E-Resources';location.hash='discover';render();});
$('#library-update').addEventListener('click',()=>{page='discover';category='Research';location.hash='discover';render();});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#resource-dialog').open){e.preventDefault();location.hash='search';go('search');}});
window.addEventListener('hashchange',()=>go(location.hash.slice(1)));
go(location.hash.slice(1)||'home');
const toolContext=document.modelContext;
if(toolContext?.registerTool){
 const lifecycle=new AbortController();
 const tool={name:'browse_library_resources',title:'Browse library resources',description:'Search the demo library and update the visible discovery feed.',inputSchema:{type:'object',properties:{query:{type:'string'},category:{type:'string',enum:categories}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||(input.query!==undefined&&typeof input.query!=='string')||(input.category!==undefined&&!categories.includes(input.category)))throw new Error('Provide a text query and a valid resource category.');category=input.category||'For You';query=input.query||'';page=query?'search':'home';location.hash=page;render();return{category,query,resources:filterResources({category,query,selectedSubjects:profile.subjects}).map(({id,title,type})=>({id,title,type}))};}};
 try{Promise.resolve(toolContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
